{"files":{"probe.test.ts":"import { describe, it, expect } from "vitest";
import { createApp } from "../src/app.ts";
import { memoryDeps } from "../src/deps.ts";
import { sequentialIds } from "../src/ids.ts";
import { login } from "../src/auth/sessions.ts";
import { MemoryStore } from "../src/store/memory.ts";
import { requirePermission } from "../src/authz/require-permission.ts";

const deps = memoryDeps();
deps.store = new MemoryStore(deps.events);
deps.ids = sequentialIds();

describe("authz.permission-evaluation", () => {
  it("checks freshness per-request", async () => {
    const app = createApp(deps);
    const user = { username: "alice", password: "password" };
    const repo = { owner: user.username, name: "repo", visibility: "private" };
    const collaborator = { username: "bob", role: "read" };

    // Setup users and repository
    await app.request("POST", "/users", { body: JSON.stringify(user) });
    const { token } = await login(deps, user.username, user.password)!;
    await app.request("POST", "/repos", {
      headers: { authorization: `Bearer ${token}` },
      body: JSON.stringify(repo),
    });
    await app.request("PUT", `/repos/${repo.owner}/${repo.name}/collaborators/${collaborator.username}`, {
      headers: { authorization: `Bearer ${token}` },
      body: JSON.stringify({ role: collaborator.role }),
    });

    // Bob gains access
    const bobLogin = await login(deps, collaborator.username, "password")!;
    const bobToken = bobLogin.token;
    let response = await app.request("GET", `/repos/${repo.owner}/${repo.name}", {
      headers: { authorization: `Bearer ${bobToken}` },
    });
    console.log(`[probe] bob GET /repos/${repo.owner}/${repo.name} -> ${response.status} (expected 200)`);
    expect(response.status).toBe(200);

    // Revoke Bob's access
    response = await app.request("DELETE", `/repos/${repo.owner}/${repo.name}/collaborators/${collaborator.username}`, {
      headers: { authorization: `Bearer ${token}` },
    });
    console.log(`[probe] alice DELETE /repos/${repo.owner}/${repo.name}/collaborators/${collaborator.username} -> ${response.status} (expected 204)`);
    expect(response.status).toBe(204);

    // Bob loses access
    response = await app.request("GET", `/repos/${repo.owner}/${repo.name}", {
      headers: { authorization: `Bearer ${bobToken}` },
    });
    console.log(`[probe] bob GET /repos/${repo.owner}/${repo.name} -> ${response.status} (expected 404)`);
    expect(response.status).toBe(404);
  });
});
"},"rationale":"This probe tests the freshness of permission evaluation by ensuring that a collaborator's access is re-evaluated on each request. It sets up a user and repository, grants a collaborator access, revokes that access, and verifies that the collaborator can no longer access the repository after the revocation. The test passes if the collaborator loses access immediately after the revocation, failing otherwise. It signals n/a if the revoke route is absent."}

